mapper.select:
WITH TIME_LIST AS( SELECT DISTINCT SHIFT_DATE FROM PWEB.WP_CALENDAR@A1PDW WHERE 1=1
AND SHOP_WEEK = #{shiftDate}
AND SHIFT_DATE = #{shiftDate}
), EQP_ID_LIST AS( SELECT EQP_ID,MODULE,EQP_G FROM PWEB.EQP_ID_USE_STD@A1PDW WHERE LENGTH(EQP_ID)= 5 AND MODULE IN('PHOTO','ETCH','TF','DIFF','WET','CMP') AND #{fab} = 'N1A1'
AND MODULE = #{module}
UNION ALL SELECT EQP_ID,MODULE,EQP_G FROM PWEB.EQP_ID_USE_STD@A3PDW WHERE LENGTH(EQP_ID)= 6 AND MODULE IN('PHOTO','ETCH','TF','DIFF','WET','CMP') AND #{fab} = 'N1A3'
AND MODULE = #{module}
),BASE_INFO AS( SELECT B.SHIFT_DATE,EQP_ID,ACTION_NAME,TIME_STAMP,ACTION_COMMENT,PPID,PRODSPEC_ID,LOT_ID,F_COMMENT FROM TIME_LIST A JOIN A1_MFG.RMS_NG_DAILY B ON A.SHIFT_DATE = B.SHIFT_DATE ) SELECT A.MODULE,A.EQP_G,B.EQP_ID,B.TIME_STAMP,B.ACTION_NAME,B.PPID,B.PRODSPEC_ID,B.LOT_ID ,DECODE(B.F_COMMENT,NULL,'N','Y')IS_RELEASE,B.F_COMMENT FROM EQP_ID_LIST A JOIN BASE_INFO B ON A.EQP_ID = B.EQP_ID ORDER BY DECODE(A.MODULE,'PHOTO',1,'ETCH',2,'TF',3,'DIFF',4,'WET',5,'CMP',6),DECODE(ACTION_NAME,'ppid_verification',1,2),A.EQP_G,B.EQP_ID

SELECT A.SHIFT_DATE,B.MODULE,B.RECIPE_COUNT,B.RELEASE_COUNT,B.ADD_COUNT FROM( SELECT TO_CHAR(TRUNC(SYSDATE-7.5/24)-ROWNUM,'YYYYMMDD')SHIFT_DATE FROM DUAL CONNECT BY ROWNUM <= 30 )A LEFT JOIN( SELECT SHIFT_DATE,MODULE,SUM(RECIPE_COUNT)RECIPE_COUNT,SUM(RELEASE_COUNT)RELEASE_COUNT,SUM(ADD_COUNT)ADD_COUNT FROM( SELECT SHIFT_DATE,FAB,MODULE,RECIPE_COUNT,RELEASE_COUNT,ADD_COUNT FROM A1_MFG.RMS_RECIPE_MONITOR_SUMMARY WHERE SHIFT_DATE BETWEEN TO_CHAR(SYSDATE-7.5/24-30 ,'YYYYMMDD') AND TO_CHAR(SYSDATE-7.5/24-1 ,'YYYYMMDD') AND FAB = #{fab}
AND MODULE = #{module}
)GROUP BY SHIFT_DATE,MODULE )B ON A.SHIFT_DATE = B.SHIFT_DATE ORDER BY A.SHIFT_DATE,DECODE(MODULE,'PHOTO',1,'ETCH',2,'TF',3,'DIFF',4,'WET',5,'CMP',6)
